(* Proof obligation: Omega glyph absorber property *)
let invariant_0035_obligation : bool =
  `!prev : routing_glyph.
     (routing_of omega prev = omega ∧ is_absorber omega)`;;

let prove_0035 : string =
  "GENERATED_UNVERIFIED: Prove Omega glyph is absorber: ∀prev. ω(prev) = ω.";;

(* INVARIANT_0036: QLG_ROUTING_LAMBDA *)
(* Proof obligation: Lambda glyph identity property *)
let invariant_0036_obligation : bool =
